def poblar_secuencias_iniciales(apps, schema_editor):
    Producto = apps.get_model("inventario", "Producto")
    SecuenciaCodigo = apps.get_model("inventario", "SecuenciaCodigo")

    prefijos_max = {}
    for prod in Producto.objects.all():
        if prod.codigo_interno and "-" in prod.codigo_interno:
            partes = prod.codigo_interno.split("-")
            prefijo = partes[0]
            try:
                num = int(partes[1])
                prod.numero_secuencia = num
                prod.save(update_fields=["numero_secuencia"])
                if prefijo not in prefijos_max or num > prefijos_max[prefijo]:
                    prefijos_max[prefijo] = num
            except (ValueError, IndexError):
                pass

    for prefijo, max_num in prefijos_max.items():
        SecuenciaCodigo.objects.update_or_create(
            prefijo=prefijo,
            defaults={"ultimo_valor": max_num},
        )


